/* Browser-local experience prototype: no orders, wallet calls or production rewards. */
const journeySteps=[['Discover','Find your people','discover'],['Belong','Make it your home','my-guild'],['Prepare','Know the match','arena'],['Compete','See your contribution','arena'],['Celebrate','Keep your story','journey']];
const matchStages=['prepare','matched','live','review','final'];
state.guildJourney=state.guildJourney||{};
function journeyGuild(){return state.membership&&guildById(state.membership.id)}
function journeyRecord(g=journeyGuild()){if(!g)return null;return state.guildJourney[g.id]||(state.guildJourney[g.id]={briefed:false,stage:'prepare',trades:[],badges:[],round:1})}
function stageTitle(s){return {prepare:'Get battle-ready',matched:'Your opponent is here',live:'The match is on',review:'Results under review',final:'A chapter worth keeping'}[s]}
function journeyCTA(){const g=journeyGuild(),r=journeyRecord(g);return !g?['discover','Find your community']:!r.briefed?['arena','Read your battle briefing']:r.stage==='final'?['journey','Your season story']:['arena',r.stage==='prepare'?'Prepare with your team':stageTitle(r.stage)]}
function journeyHomePanel(){const g=journeyGuild(),r=journeyRecord(g),cta=journeyCTA(),active=!g?0:!r.briefed?1:r.stage==='prepare'||r.stage==='matched'?2:r.stage==='final'?4:3;return `<section class="journey-home"><div class="journey-home-heading"><div><span class="page-eyebrow">YOUR NEXT MOVE</span><h2>${g?'Your team. Your part in the story.':'From finding your people to making your mark.'}</h2><p>${g?escapeHtml(g.name)+' · '+stageTitle(r.stage):'A shared identity. A real opponent. A story that continues after the match.'}</p></div>${link(cta[0],cta[1]+' '+arrow(),'primary button')}</div><div class="journey-rail">${journeySteps.map(([t,d,path],i)=>`<a href="#/${path}" class="${i===active?'active':i<active?'complete':''}"><span>${i<active?icon('check'):'0'+(i+1)}</span><div><strong>${t}</strong><small>${d}</small></div></a>`).join('')}</div><div class="journey-mode-links"><a href="#/rankings">${icon('chart')} Season leaderboard <small>The long game</small>${arrow()}</a><a href="#/arena">${icon('swords')} Guild vs Guild <small>Your next opponent</small>${arrow()}</a><a href="#/journey">${icon('shield')} My season story <small>Your contribution & memories</small>${arrow()}</a></div></section>`}
const journeyPreviousHome=seasonHome;seasonHome=function(){return journeyPreviousHome()};
const journeyPreviousDashboard=myGuildPage;myGuildPage=function(tab='overview',preview=false){let html=journeyPreviousDashboard(tab,preview);if(tab==='overview'&&!preview&&journeyGuild())html=html.replace('</section>','</section>'+journeyHomePanel());return html};
function battleOpponent(g){return worldGuilds().find(x=>x.id!==g.id)||guildById('memeland')}
function matchTotals(g,r){const personal=r.trades.reduce((s,t)=>s+t.notional,0);return {personal,team:6800000+personal,opponent:6200000}}
function battleState(){const g=journeyGuild();return {g:g||guildById('huddle'),r:g?journeyRecord(g):{stage:'prepare',briefed:false,trades:[],badges:[],round:1},member:!!g}}
function battleStageBody(g,r,member){const op=battleOpponent(g),tot=matchTotals(g,r),owner=state.membership?.role==='owner';if(r.stage==='prepare')return `<div class="battle-preparation"><div><span class="page-eyebrow">01 · PREPARE TOGETHER</span><h2>A clear beginning.<br>A shared commitment.</h2><p>Guild leaders manage the team entry. Every member gets a clear briefing and chooses how to participate.</p><div class="battle-checklist"><span>${icon(r.briefed?'check':'shield')} Read the match briefing ${r.briefed?'<b>READY</b>':''}</span><span>${icon('users')} One community, one guild · Unlimited members</span><span>${icon('chart')} Know how eligible activity is attributed</span><span>${icon('shield')} Your capital and trading decisions stay yours</span></div>${member?`<button class="primary" data-battle-brief>${r.briefed?'Review briefing':'Read briefing & get ready'} ${arrow()}</button>`:link('discover','Find your guild to participate '+arrow(),'primary button')}</div><aside><span class="journey-small-label">THE CAPTAIN’S ROLE</span><h3>Set the direction.<br>Bring the team together.</h3><p>Review event terms, confirm team entry, share the briefing and track team participation.</p>${member?owner?link('competition/entry','Review team entry '+arrow(),'secondary button'):'<div class="journey-note">You are a member. Live team registration will be managed by your guild leader.</div>':''}<small>In this prototype, members can advance a sample match after reading the briefing.</small>${member?`<button class="text-button" data-battle-advance="matched" ${!r.briefed?'disabled':''}>Preview matchmaking ${arrow()}</button>`:''}</aside></div>`;
if(r.stage==='matched')return `<div class="battle-matched"><span class="page-eyebrow">02 · A SHARED CHALLENGE</span><h2>Meet your next opponent.</h2><div class="journey-versus"><div><img src="${emblem(g)}" alt=""><strong>${escapeHtml(g.name)}</strong><small>YOUR TEAM</small></div><span>VS</span><div><img src="${emblem(op)}" alt=""><strong>${escapeHtml(op.name)}</strong><small>THE CHALLENGER</small></div></div><p>A head-to-head round within the wider season. Battle progression and the multi-guild standings remain separate.</p><div class="journey-note">Sample pairing · Match duration, eligibility, ranking bands and scoring are pending design.</div><div class="journey-action-row"><button class="primary" data-battle-advance="live">Enter sample match ${arrow()}</button><button class="secondary" data-journey-chat>Open team chat ${icon('users')}</button></div></div>`;
if(r.stage==='live')return `<div class="battle-live-head"><div><span class="page-eyebrow">03 · CONTRIBUTE & FOLLOW THE CHASE</span><h2>You trade individually.<br>Your team sees the impact.</h2><p>Review each eligible contribution and its status in one place.</p></div><div><button class="primary" data-contribution-demo>Add a simulated contribution ${arrow()}</button><button class="secondary" data-journey-chat>Team chat ${icon('users')}</button></div></div><div class="journey-score"><div><img src="${emblem(g)}" alt=""><span>${escapeHtml(g.name)}<strong>${compactMoney(tot.team)}</strong></span><b>VS</b><span>${escapeHtml(op.name)}<strong>${compactMoney(tot.opponent)}</strong></span><img src="${emblem(op)}" alt=""></div><div class="journey-score-track"><i style="width:${tot.team/(tot.team+tot.opponent)*100}%"></i></div><small>Sample score based on notional volume · Final scoring is not configured.</small></div>${contributionLedger(r)}<div class="journey-action-row"><button class="secondary" data-battle-advance="review">Preview match close ${arrow()}</button>${link('rankings','View season standings '+arrow(),'text-button')}</div>`;
if(r.stage==='review')return `<div class="battle-review"><span class="journey-review-icon">${icon('clock')}</span><span class="page-eyebrow">04 · VERIFY BEFORE FINALISING</span><h2>The match is over.<br>The story needs a clear result.</h2><p>Live results would remain provisional while eligible trades, attribution and exclusions are checked.</p><div class="review-explain"><span>${icon('check')} Team score recorded</span><span>${icon('clock')} Eligible contributions under review</span><span>${icon('lock')} No rewards available during review</span></div>${contributionLedger(r)}<button class="primary" data-battle-advance="final">Preview verified result ${arrow()}</button></div>`;
const won=tot.team>tot.opponent;return `<div class="battle-final"><span class="final-emblem">${icon('trophy')}</span><span class="page-eyebrow">05 · FINAL RESULT PREVIEW · ROUND ${r.round}</span><h2>${won?'A shared win.':'A shared chapter.'}<br>A step higher together.</h2><p>${escapeHtml(g.name)} vs ${escapeHtml(op.name)} · ${won?'Sample victory':'Sample match complete'}</p><div class="journey-result-grid"><div><small>TEAM SCORE · SAMPLE</small><strong>${compactMoney(tot.team)}</strong><span>Opponent ${compactMoney(tot.opponent)}</span></div><div><small>YOUR SIMULATED CONTRIBUTION</small><strong>${compactMoney(tot.personal)}</strong><span>${r.trades.length} demo record${r.trades.length===1?'':'s'}</span></div><div><small>ARENA JOURNEY</small><strong>Floor ${1+r.badges.length}</strong><span>Cosmetic progression preview</span></div></div><div class="journey-note">Rewards and promotion rules will be configured separately. This result creates no live rank change or financial entitlement.</div><div class="journey-action-row">${r.badges.includes(r.round)?'<span class="journey-saved">'+icon('check')+' Round memory saved</span>':'<button class="primary" data-battle-memory>Save round badge '+icon('shield')+'</button>'}${link('journey','See my season story '+arrow(),'secondary button')}<button class="text-button" data-next-round>Prepare next sample round ${arrow()}</button></div></div>`}
function contributionLedger(r){return `<section class="contribution-ledger"><div><h3>Your contribution journal</h3><span>SIMULATED ACTIVITY ONLY</span></div>${r.trades.length?`<div class="journey-ledger-scroll"><table><thead><tr><th>Market</th><th>Side</th><th>Notional</th><th>Attribution</th><th>Status</th></tr></thead><tbody>${r.trades.map(t=>`<tr><td>${t.market}</td><td>${t.side}</td><td>${compactMoney(t.notional)}</td><td>This guild · Round ${r.round}</td><td>${r.stage==='final'?'Verified demo':r.stage==='review'?'Under review':'Sample eligible'}</td></tr>`).join('')}</tbody></table></div>`:`<div class="journey-ledger-empty">${icon('chart')} No simulated activity yet. Explore a contribution record without placing an order.</div>`}<small>In production: individual trade IDs, timestamps, eligibility reasons and exclusions would appear here.</small></section>`}
arenaPage=function(tab='overview'){const {g,r,member}=battleState();return breadcrumb(`${link('','Guild World')}<span>/</span>Guild Battle`)+heading('GUILD VS GUILD · THE NEXT CHAPTER','ONE TEAM.<br><span>ONE SHARED CHALLENGE.</span>','Prepare, meet an opponent, follow your contribution and keep a record of the result.')+`<div class="battle-prototype-note">${icon('info')} INTERACTIVE SAMPLE MATCH · Local prototype, no real trades, registration or rewards.</div><div class="battle-stage-rail">${matchStages.map((s,i)=>`<div class="${r.stage===s?'active':matchStages.indexOf(r.stage)>i?'complete':''}"><span>0${i+1}</span><strong>${['Prepare','Opponent','Live match','Review','Result'][i]}</strong></div>`).join('')}</div><div class="battle-journey-shell">${battleStageBody(g,r,member)}</div><div class="battle-support-grid"><a href="#/competition/rules">${icon('shield')}<h3>Understand the competition</h3><p>Eligibility, attribution and the route from provisional to final.</p>${arrow()}</a><a href="#/rankings">${icon('trophy')}<h3>The wider season continues</h3><p>A shared leaderboard for every guild, alongside head-to-head rounds.</p>${arrow()}</a><a href="#/journey">${icon('users')}<h3>Keep your own story</h3><p>Your contribution journal, round memories and next step.</p>${arrow()}</a></div>`};
function seasonStoryPage(){const g=journeyGuild(),r=journeyRecord(g);return breadcrumb('Your season story')+heading('BELONG. CONTRIBUTE. REMEMBER.','YOUR PART.<br><span>A SHARED STORY.</span>','A clear place for your community, contributions and the moments you build together.')+(!g?`<div class="world-member-lock">${icon('users')}<h2>Your story starts with your people.</h2><p>Visit a community and join a guild to begin your member journey.</p>${link('discover','Find your guild '+arrow(),'primary button')}</div>`:`${communityThemeBanner(communityById(g.id)||{...g,community:g.name,tag:'Your community. Your shared chapter.',art:'assets/world-arena.webp'},true)}${journeyHomePanel()}<div class="story-grid"><section class="workspace-panel story-record">${sectionTitle('Your round memories','Cosmetic demo badges · No financial value')}<div class="story-badges">${r.badges.length?r.badges.map(n=>`<div>${icon('shield')}<strong>Round ${n}</strong><span>Shared chapter</span></div>`).join(''):'<p>Your first round badge will appear here after a sample match finishes.</p>'}</div><div class="journey-tower-progress"><img src="assets/world-arena.webp" alt="XOX Arena Tower"><div><small>YOUR ARENA JOURNEY</small><h2>Floor ${1+r.badges.length}</h2><p>Each saved round adds a cosmetic step in this prototype. Final promotion conditions remain adjustable.</p>${link('arena','Continue your battle '+arrow(),'primary button')}</div></div></section><section class="workspace-panel story-record">${sectionTitle('Your member choices','Participation is personal')}<div class="story-choice-list"><button data-journey-chat>${icon('users')} Talk with your team ${arrow()}</button>${link('leaders','Explore leader performance '+arrow())}${link('my-guild/copy','Review optional guild leader copying '+arrow())}${link('competition/results','Explore season result states '+arrow())}</div><div class="journey-note">Copying is a separate decision and only available to actual members of the leader’s guild. It is never required to join or participate.</div></section></div>${contributionLedger(r)}${(r.history||[]).map(h=>`<div class="story-archive-heading">ROUND ${h.round} · ARCHIVED JOURNAL</div>`+contributionLedger({...h,stage:'final'})).join('')}`)}
function persistJourney(){save();renderRoute(false)}
const journeyBaseRender=renderRoute;renderRoute=function(scroll=true){journeyBaseRender(scroll);if(routePath==='journey'){document.querySelector('#overview').hidden=true;$('#workspace').hidden=false;$('#workspace').innerHTML=seasonStoryPage();document.title='Your season story — XOX Guilds'}};
function openBriefing(){const r=journeyRecord();if(!r)return;open(`<div class="journey-modal"><span class="page-eyebrow">BATTLE BRIEFING</span><h2>Be part of the team.<br>Keep your own judgement.</h2><p>A round pairs your guild with one opponent. Your own contribution journal explains how activity is attached to the team.</p><ul><li>One active guild; no member limit.</li><li>The season leaderboard and head-to-head rounds are separate views.</li><li>This sample match uses simulated notional values; final scoring and rewards remain to be designed.</li><li>No real order is placed here. Copying is optional and separate.</li></ul><button class="primary" data-confirm-briefing>Got it · Ready with my team ${icon('check')}</button></div>`)}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;const g=journeyGuild(),r=journeyRecord(g);if(b.hasAttribute('data-battle-brief'))openBriefing();if(b.hasAttribute('data-confirm-briefing')&&r){r.briefed=true;modal.close();persistJourney();toast('Briefing read. Your sample match is ready to explore.')}if(b.dataset.battleAdvance&&r){const next=matchStages.indexOf(b.dataset.battleAdvance),current=matchStages.indexOf(r.stage);if(!r.briefed||next!==current+1)return;r.stage=matchStages[next];persistJourney()}if(b.hasAttribute('data-journey-chat')){if(g)openGuildChat(g.id);else toast('Join a guild to enter its team chat.')}if(b.hasAttribute('data-contribution-demo')&&r&&r.stage==='live'){open(`<div class="journey-modal"><span class="page-eyebrow">SIMULATED CONTRIBUTION · NO ORDER</span><h2>See how a contribution appears.</h2><p>This creates a fictional activity record in this browser. It does not open a position, connect a wallet or affect live standings.</p><form id="contribution-demo-form" class="form"><label for="contribution-market">Market</label><select id="contribution-market" name="market"><option>BTC / USDT</option><option>ETH / USDT</option><option>SOL / USDT</option></select><label for="contribution-side">Side</label><select id="contribution-side" name="side"><option>Long</option><option>Short</option></select><label for="contribution-notional">Simulated notional · USDT</label><input id="contribution-notional" name="notional" type="number" required min="1" max="100000" step="1" value="1000"><label class="check"><input type="checkbox" required><span>I understand this is fictional activity and no real trade will be placed.</span></label><button type="submit" class="primary">Add demo record ${arrow()}</button></form></div>`)}if(b.hasAttribute('data-battle-memory')&&r&&r.stage==='final'&&!r.badges.includes(r.round)){r.badges.push(r.round);persistJourney();toast('Round badge saved to your season story.')}if(b.hasAttribute('data-next-round')&&r&&r.stage==='final'){if(!r.badges.includes(r.round)){toast('Save this round badge before beginning the next chapter.');return}r.round++;r.stage='prepare';r.briefed=false;r.history=r.history||[];r.history.push({round:r.round-1,trades:r.trades});r.trades=[];persistJourney()}});
document.addEventListener('submit',e=>{if(e.target.id!=='contribution-demo-form')return;e.preventDefault();if(!e.target.checkValidity())return;const r=journeyRecord();if(!r||r.stage!=='live')return;const f=new FormData(e.target),v=Number(f.get('notional'));if(!Number.isFinite(v)||v<1||v>100000||!Number.isInteger(v))return;const market=f.get('market'),side=f.get('side');if(!['BTC / USDT','ETH / USDT','SOL / USDT'].includes(market)||!['Long','Short'].includes(side))return;r.trades.push({market,side,notional:v,at:new Date().toISOString()});modal.close();persistJourney();toast('Simulated contribution recorded. No order was placed.')});
renderRoute(false);
